"""Generate the plain-Markdown log-code reference from the stable registry."""

from __future__ import annotations

import argparse
import logging
from pathlib import Path

from dendrux._codes import REGISTRY

DEFAULT_OUTPUT = Path(__file__).resolve().parents[3] / "docs/reference/log-codes.mdx"


def render() -> str:
    """Return deterministic operator documentation for every registered code."""
    lines = [
        "# Log codes and what to do",
        "",
        "> Generated by `packages/python/tools/gen_log_codes.py`.",
        "> Edit the registry, then regenerate.",
        "",
        "Call sites move to `log_code` in a later release. Lines emitted by the helper carry",
        "`code` and `kind`, plus `run_id` and `tenant_id` when set.",
        "Other fields are declared per code. Identifiers are validated; text uses closed enums.",
        "With `DENDRUX_STRICT_LOG_FIELDS=1`, invalid fields raise. Otherwise they are dropped",
        "with one `log_field_dropped` diagnostic. Unregistered code objects always raise.",
        "Drop diagnostics contain only a count and validated identifiers, never rejected values.",
        "Vendor messages and payloads are never log fields. Custom provider names log as `custom`.",
        "",
        "Provider codes use closed per-provider tables.",
        "Present unknown codes become `provider_unknown`.",
        "Missing or invalid codes remain unset. Category and HTTP status remain independent.",
        "",
    ]
    for kind in sorted({code.kind for code in REGISTRY.values()}):
        lines += [
            f"## {'MCP' if kind == 'mcp' else kind.replace('_', ' ').title()}",
            "",
            "| Code | Level | Fields | Fires when | Do |",
            "| --- | --- | --- | --- | --- |",
        ]
        for code in sorted(REGISTRY.values(), key=lambda code: code.name):
            if code.kind == kind:
                fields = ", ".join(f"`{field}`" for field in sorted(code.fields))
                lines.append(
                    f"| `{code.name}` | {logging.getLevelName(code.level)} | {fields} | "
                    f"{code.fires_when} | {code.do} |"
                )
        lines.append("")
    lines += [
        "## What to alert on",
        "",
        "- `reclaim_limit` at any rate: inspect the run and worker crashes.",
        "- `run_fenced` above a small sustained rate: inspect worker turnover and lease sizing.",
        "- `notifier_degraded` lasting more than one minute: inspect the listener connection.",
        "- `sweep_cap_reached` on every sweep: run more often or raise the scan bound.",
        "- `follow_capacity` or `follow_tenant_capacity`: reduce followers or raise their cap.",
        "- `log_field_dropped`: fix the emitting call without adding raw values to diagnostics.",
        "",
    ]
    return "\n".join(lines)


def main() -> None:
    """Write the reference to the repository or an explicitly selected path."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    output = parser.parse_args().output
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render())


if __name__ == "__main__":
    main()
